def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.
    """
    from heapq import heappop, heappush

    def locate(x, y):
        i, j = x // K, y // K
        return (i, j, y - j * K) if (i + j) % 2 == 0 else (i, j, x - i * K)

    start, goal = locate(S_x, S_y), locate(T_x, T_y)
    if start == goal:
        return 0
    si, sj, _ = start
    gi, gj, _ = goal
    if K > 200 or abs(gi - si) + abs(gj - sj) > 100:
        # Long paths can cross boundaries in an alternating-axis pattern.
        # This also keeps work independent of the coordinate magnitudes.
        return abs(gi - si) + abs(gj - sj)

    lo_i, hi_i = min(si, gi) - 2, max(si, gi) + 2
    lo_j, hi_j = min(sj, gj) - 2, max(sj, gj) + 2

    def is_h(i, j):
        return (i + j) % 2 == 0

    def neighbors(state):
        i, j, k = state
        h = is_h(i, j)
        if k > 0:
            yield (i, j, k - 1)
        if k + 1 < K:
            yield (i, j, k + 1)
        if h:
            if lo_i <= i - 1:
                yield (i - 1, j, K - 1)
            if i + 1 <= hi_i:
                yield (i + 1, j, 0)
            if k == 0 and j - 1 >= lo_j:
                for nk in range(K):
                    yield (i, j - 1, nk)
            if k == K - 1 and j + 1 <= hi_j:
                for nk in range(K):
                    yield (i, j + 1, nk)
        else:
            if j - 1 >= lo_j:
                yield (i, j - 1, K - 1)
            if j + 1 <= hi_j:
                yield (i, j + 1, 0)
            if k == 0 and i - 1 >= lo_i:
                for nk in range(K):
                    yield (i - 1, j, nk)
            if k == K - 1 and i + 1 <= hi_i:
                for nk in range(K):
                    yield (i + 1, j, nk)

    distances = {start: 0}
    heap = [(0, start)]
    while heap:
        distance, state = heappop(heap)
        if distance != distances[state]:
            continue
        if state == goal:
            return distance
        for nxt in neighbors(state):
            new_distance = distance + 1
            if new_distance < distances.get(nxt, 10**100):
                distances[nxt] = new_distance
                heappush(heap, (new_distance, nxt))
    return abs(gi - si) + abs(gj - sj)

