def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Given n and k, decide whether some n by n binary matrix has exactly k
    entries that are invariant among all matrices with the same row and column
    sums.

    For a fixed pair of margins, regard each cell as a directed edge: a 1 is
    directed from its column to its row and a 0 from its row to its column.
    A cell can change in another realization exactly when its edge belongs to
    a directed cycle (an alternating cycle).  The invariant cells are thus the
    edges between strongly connected components, together with invariant
    cells inside a component.
    """
    if not (0 <= k <= n * n):
        return False

    # Sizes of the nontrivial alternating components determine the number of
    # cells outside those components.  A component of size one has its sole
    # cell fixed.  Enumerate component sizes with a small dynamic program.
    # Components of size two do not produce a nontrivial alternating cycle;
    # they are accounted for as fixed cells.
    dp = {0: {0}}
    for used in range(n + 1):
        if used not in dp:
            continue
        for squares in tuple(dp[used]):
            for size in range(2, n - used + 1):
                dp.setdefault(used + size, set()).add(squares + size * size)

    # For a partition into alternating components of sizes >= 3 and singleton
    # components, all cells outside the large components are fixed.
    for used, square_sums in dp.items():
        if used > n:
            continue
        singles = n - used
        for squares in square_sums:
            fixed = n * n - squares
            if fixed == k:
                return True
    return False

