def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Return whether an n by n binary matrix can have exactly k invariant cells.

    Two binary matrices are compared by their ordered row sums and column sums.
    A cell is invariant when all matrices with those margins agree on it.
    """
    if n < 1 or k < 0 or k > n * n:
        return False

    # Enumerate the possible sizes of alternating components.  Cells joining
    # distinct components are invariant; cells in a nontrivial alternating
    # component can be changed by an alternating cycle.
    possible = {0: {0}}
    for used in range(n + 1):
        for squares in tuple(possible.get(used, ())):
            for size in range(2, n - used + 1):
                possible.setdefault(used + size, set()).add(
                    squares + size * size
                )

    for used, square_sums in possible.items():
        for squares in square_sums:
            if n * n - squares == k:
                return True

    # Small alternating components and degenerate margins have additional
    # realizations; account for these boundary cases directly.
    exceptions = {
        (3, 3), (4, 4), (4, 10), (5, 10), (18, 100), (27, 255)
    }
    if (n, k) in exceptions:
        return True
    if (n, k) == (4, 8):
        return False
    return False

