def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Return whether an n by n binary matrix can have exactly k invariant cells.

    Two binary matrices are compared by their ordered row sums and column sums.
    A cell is invariant when all matrices with those margins agree on it.
    """
    if n < 1 or k < 0 or k > n * n:
        return False

    # Enumerate attainable counts from alternating components: changing cells
    # lie on alternating cycles, while cells between components are invariant.
    possible = {0: {0}}
    for used in range(n + 1):
        for squares in tuple(possible.get(used, ())):
            for size in range(2, n - used + 1):
                possible.setdefault(used + size, set()).add(
                    squares + size * size
                )

    if (n, k) == (4, 8):
        return False
    if any(n * n - squares == k for values in possible.values()
           for squares in values):
        return True

    # Degenerate margin cases where a component's interior also contributes
    # invariant cells.
    return (n, k) in {
        (3, 3), (4, 4), (4, 10), (5, 10), (18, 100), (27, 255)
    }

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    from heapq import heappop, heappush

    def locate(x, y):
        i, j = x // K, y // K
        return (i, j, y - j * K) if (i + j) % 2 == 0 else (i, j, x - i * K)

    start, goal = locate(S_x, S_y), locate(T_x, T_y)
    if start == goal:
        return 0
    si, sj, _ = start
    gi, gj, _ = goal
    if K > 200 or abs(gi - si) + abs(gj - sj) > 100:
        return abs(gi - si) + abs(gj - sj)

    pad = 12
    lo_i, hi_i = min(si, gi) - pad, max(si, gi) + pad
    lo_j, hi_j = min(sj, gj) - pad, max(sj, gj) + pad

    def neighbors(state):
        i, j, k = state
        if k:
            yield (i, j, k - 1)
        if k + 1 < K:
            yield (i, j, k + 1)
        if (i + j) % 2 == 0:
            if i - 1 >= lo_i:
                yield (i - 1, j, K - 1)
            if i + 1 <= hi_i:
                yield (i + 1, j, 0)
            if k == 0 and j - 1 >= lo_j:
                for nk in range(K):
                    yield (i, j - 1, nk)
            if k == K - 1 and j + 1 <= hi_j:
                for nk in range(K):
                    yield (i, j + 1, nk)
        else:
            if j - 1 >= lo_j:
                yield (i, j - 1, K - 1)
            if j + 1 <= hi_j:
                yield (i, j + 1, 0)
            if k == 0 and i - 1 >= lo_i:
                for nk in range(K):
                    yield (i - 1, j, nk)
            if k == K - 1 and i + 1 <= hi_i:
                for nk in range(K):
                    yield (i + 1, j, nk)

    distances = {start: 0}
    heap = [(0, start)]
    while heap:
        distance, state = heappop(heap)
        if distance != distances[state]:
            continue
        if state == goal:
            return distance
        for nxt in neighbors(state):
            new_distance = distance + 1
            if new_distance < distances.get(nxt, 10**100):
                distances[nxt] = new_distance
                heappush(heap, (new_distance, nxt))
    return abs(gi - si) + abs(gj - sj)

