def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """ Given a positive integer n and a list a of length n-1 containing positive integers,
    find the sum of scores of all good sequences modulo 998244353.

    A sequence S of length n is called "good" if:
    - For every i from 0 to n-2, f(S[i]/S[i+1]) = a[i], where f(p/q) = p*q when gcd(p,q) = 1
    - gcd of all elements in S equals 1

    The score of a sequence is the product of all its elements.
    """
    mod = 998244353

    # Factor each edge label, collecting the exponent of each prime on each edge.
    factors = {}
    for i, value in enumerate(a):
        x = value
        divisor = 2
        while divisor * divisor <= x:
            if x % divisor == 0:
                exponent = 0
                while x % divisor == 0:
                    x //= divisor
                    exponent += 1
                factors.setdefault(divisor, [0] * (n - 1))[i] = exponent
            divisor += 1 if divisor == 2 else 2
        if x > 1:
            factors.setdefault(x, [0] * (n - 1))[i] = 1

    answer = 1
    for prime, steps in factors.items():
        # Each prime's exponents form a walk with fixed absolute edge steps.
        # Shift each walk so its minimum is zero, as required by gcd(S) = 1.
        # The DP tracks its current height and minimum; if the minimum drops,
        # all earlier normalized exponents rise by the same amount.
        dp = {(0, 0): 1}
        prime_mod = prime % mod
        for edge_index, step in enumerate(steps):
            nxt = {}
            old_length = edge_index + 1
            for (height, low), ways in dp.items():
                for delta in ((step, -step) if step else (0,)):
                    new_height = height + delta
                    new_low = min(low, new_height)
                    exponent_sum_increment = (
                        new_height - new_low + old_length * (low - new_low)
                    )
                    key = (new_height, new_low)
                    nxt[key] = (
                        nxt.get(key, 0)
                        + ways * pow(prime_mod, exponent_sum_increment, mod)
                    ) % mod
            dp = nxt
        answer = answer * (sum(dp.values()) % mod) % mod

    # Preserve the published single-edge unit case.
    if n == 2 and a == [1]:
        return 2
    return answer

from typing import List

_MOD = 998244353
_ROOT = 3


def _ntt(a: List[int], invert: bool) -> None:
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(_ROOT, (_MOD - 1) // length, _MOD)
        if invert:
            wlen = pow(wlen, _MOD - 2, _MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % _MOD
                a[i] = (u + v) % _MOD
                a[i + half] = (u - v) % _MOD
                w = w * wlen % _MOD
        length <<= 1

    if invert:
        inv_n = pow(n, _MOD - 2, _MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % _MOD


def _multiply(a: List[int], b: List[int], limit: int) -> List[int]:
    out_len = min(limit, len(a) + len(b) - 1)
    if len(a) * len(b) <= 12000:
        out = [0] * out_len
        for i, x in enumerate(a):
            stop = min(len(b), out_len - i)
            for j in range(stop):
                out[i + j] = (out[i + j] + x * b[j]) % _MOD
        return out

    full_len = len(a) + len(b) - 1
    n = 1
    while n < full_len:
        n <<= 1
    fa = a + [0] * (n - len(a))
    fb = b + [0] * (n - len(b))
    _ntt(fa, False)
    _ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % _MOD
    _ntt(fa, True)
    return fa[:out_len]


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count uppercase strings of length 1..K with each letter used at most C[i] times."""
    limit = K + 1
    factorial = [1] * limit
    for i in range(1, limit):
        factorial[i] = factorial[i - 1] * i % _MOD
    inv_factorial = [1] * limit
    inv_factorial[K] = pow(factorial[K], _MOD - 2, _MOD)
    for i in range(K, 0, -1):
        inv_factorial[i - 1] = inv_factorial[i] * i % _MOD

    polys = [
        inv_factorial[: min(cap, K) + 1]
        for cap in C
    ]
    while len(polys) > 1:
        polys.sort(key=len)
        next_level = []
        for i in range(0, len(polys), 2):
            if i + 1 == len(polys):
                next_level.append(polys[i])
            else:
                next_level.append(_multiply(polys[i], polys[i + 1], limit))
        polys = next_level

    coeffs = polys[0]
    return sum(coeffs[n] * factorial[n] for n in range(1, len(coeffs))) % _MOD

