from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play the modified tic-tac-toe game optimally and return its winner."""
    lines = (
        (0, 1, 2), (3, 4, 5), (6, 7, 8),
        (0, 3, 6), (1, 4, 7), (2, 5, 8),
        (0, 4, 8), (2, 4, 6),
    )
    values = [value for row in grid for value in row]
    owners = [0] * 9  # 0 empty, 1 Takahashi, -1 Aoki
    scores = [0, 0]

    def solve(turn: int, remaining: int) -> int:
        # Return 1 when Takahashi wins with optimal play, -1 when Aoki wins.
        if remaining == 0:
            return 1 if scores[0] > scores[1] else -1

        best = -2 if turn == 1 else 2
        for cell in range(9):
            if owners[cell]:
                continue
            owners[cell] = turn
            scores[0 if turn == 1 else 1] += values[cell]

            won_line = any(all(owners[pos] == turn for pos in line) for line in lines)
            if won_line:
                result = turn
            else:
                result = solve(-turn, remaining - 1)

            scores[0 if turn == 1 else 1] -= values[cell]
            owners[cell] = 0

            if turn == 1:
                best = max(best, result)
                if best == 1:
                    break
            else:
                best = min(best, result)
                if best == -1:
                    break
        return best

    return "Takahashi" if solve(1, 9) == 1 else "Aoki"

from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]
    """
    def prefix(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        length = len(digits)
        max_sum = 9 * length
        answer = 0

        # Numbers containing a zero have digit product zero, so they are
        # beautiful. Count these directly.
        @lru_cache(None)
        def zero_count(pos: int, tight: bool, started: bool, has_zero: bool) -> int:
            if pos == length:
                return int(started and has_zero)
            limit = digits[pos] if tight else 9
            total = 0
            for d in range(limit + 1):
                next_started = started or d != 0
                next_zero = has_zero or (next_started and d == 0)
                total += zero_count(pos + 1, tight and d == limit, next_started, next_zero)
            return total

        answer += zero_count(0, True, False, False)

        # For numbers without zero, track the digit product modulo the final
        # digit sum. Leading zeroes are skipped and do not affect the product.
        for target_sum in range(1, max_sum + 1):
            @lru_cache(None)
            def dp(pos: int, remaining: int, product_mod: int, tight: bool) -> int:
                if remaining < 0 or remaining > 9 * (length - pos):
                    return 0
                if pos == length:
                    return int(remaining == 0 and product_mod == 0)
                limit = digits[pos] if tight else 9
                total = 0
                for d in range(min(limit, remaining) + 1):
                    if d == 0:
                        continue
                    total += dp(pos + 1, remaining - d,
                                (product_mod * d) % target_sum,
                                tight and d == limit)
                # A leading zero may occur only before the number starts.
                if pos == 0:
                    total += dp(pos + 1, remaining, product_mod, False)
                return total

            # The all-positive-digit path above skips zeroes, while the one
            # optional leading zero handles the shorter representations.
            answer += dp(0, target_sum, 1 % target_sum, True)
        return answer

    return prefix(r) - prefix(l - 1)

