from collections import deque

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s == t:
        return 0
    if len(s) != n or len(t) != n or s.count("B") != t.count("B"):
        return -1
    start, goal = s + "__", t + "__"
    q = deque([(start, 0)])
    seen = {start}
    while q:
        state, d = q.popleft()
        holes = [i for i, c in enumerate(state) if c == "_"]
        for i in range(n + 1):
            a, b = state[i], state[i + 1]
            if a == "_" or b == "_":
                continue
            nxt = list(state)
            nxt[holes[0]], nxt[holes[1]] = b, a
            nxt[i] = nxt[i + 1] = "_"
            nxt = "".join(nxt)
            if nxt == goal:
                return d + 1
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, d + 1))
    return -1

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count simple paths of K moves through empty grid cells.

    A path is counted once for each ordered sequence of K+1 cells, with any
    empty cell allowed as its starting point.
    """
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == "."]
    if K < 0 or len(cells) <= K:
        return 0

    index = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            j = index.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    total = 0

    def search(pos: int, remaining: int, visited: int) -> int:
        if remaining == 0:
            return 1
        count = 0
        for nxt in neighbors[pos]:
            bit = 1 << nxt
            if not visited & bit:
                count += search(nxt, remaining - 1, visited | bit)
        return count

    for start in range(len(cells)):
        total += search(start, K, 1 << start)
    return total

from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Given N sections to monitor on a conveyor belt, find the minimum cost to monitor all sections."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # For each section, only the least number of type-2 sensors needed for a
    # chosen number of type-1 sensors can be useful.
    dp = {(0, 0): 0}
    for length in sections[:n]:
        max_a = min(k1, (length + l1 - 1) // l1)
        max_b = min(k2, (length + l2 - 1) // l2)
        options = []
        for a in range(max_a + 1):
            b = max(0, (length - a * l1 + l2 - 1) // l2)
            if b <= max_b:
                options.append((a, b, a * c1 + b * c2))

        # Remove choices that use at least as many sensors of both types and
        # cost at least as much as another choice.
        frontier = []
        for a, b, cost in options:
            if any(aa <= a and bb <= b and cc <= cost
                   for aa, bb, cc in options if (aa, bb, cc) != (a, b, cost)):
                continue
            frontier.append((a, b, cost))

        nxt = {}
        for (used1, used2), cost in dp.items():
            for a, b, extra in frontier:
                x, y = used1 + a, used2 + b
                if x <= k1 and y <= k2:
                    total = cost + extra
                    if total < nxt.get((x, y), float("inf")):
                        nxt[(x, y)] = total
        dp = nxt
        if not dp:
            return -1

    return min(dp.values()) if dp else -1

