def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences over 1..K with every length-M subsequence
    except X, modulo 998244353."""
    from functools import lru_cache
    from math import comb

    MOD = 998244353

    @lru_cache(None)
    def surj(q, n):
        if n < q:
            return 0
        return sum((-1 if j & 1 else 1) * comb(q, j) * pow(q - j, n, MOD)
                   for j in range(q + 1)) % MOD

    @lru_cache(None)
    def surj_end(q, n):
        if q < 1 or n < q:
            return 0
        return sum((-1 if j & 1 else 1) * comb(q - 1, j) *
                   pow(q - j, n - 1, MOD) for j in range(q)) % MOD

    @lru_cache(None)
    def state_count(alphabet, pattern, length):
        """Words whose greedy subsequence matcher ends at state len(pattern)-1."""
        r = len(pattern)
        dp = [0] * (r + 1)
        dp[0] = 1
        q = len(alphabet)
        for _ in range(length):
            ndp = [0] * (r + 1)
            for j, value in enumerate(dp):
                if not value:
                    continue
                if j < r:
                    ndp[j] = (ndp[j] + value * (q - 1)) % MOD
                    ndp[j + 1] = (ndp[j + 1] + value) % MOD
                else:
                    ndp[j] = value * q % MOD
            dp = ndp
        return dp[r - 1]

    @lru_cache(None)
    def suffix_all(alphabet, pattern, length, last=None):
        """P occurs, and every alphabet symbol occurs after its first completion."""
        q, r = len(alphabet), len(pattern)
        if any(x not in alphabet for x in pattern):
            return 0
        ans = 0
        for prefix_len in range(length - r + 1):
            ways = state_count(alphabet, pattern, prefix_len)
            rem = length - prefix_len - 1
            if last is None:
                ways *= surj(q, rem)
            else:
                if last not in alphabet:
                    continue
                ways *= surj_end(q, rem, alphabet.index(last) + 1)
            ans = (ans + ways) % MOD
        return ans

    @lru_cache(None)
    def count(alphabet, pattern, n):
        m = len(pattern)
        if n < m:
            return 0
        if m == 1:
            q = len(alphabet) - 1
            return surj(q, n) if pattern[0] in alphabet else 0

        p, b = pattern[:-1], pattern[-1]
        q_alphabet = tuple(x for x in alphabet if x != b)
        if len(q_alphabet) != len(alphabet) - 1:
            return 0
        ans = 0
        if p[-1] == b:
            for L in range(1, n + 1):
                ans += count(alphabet, p, L - 1) * surj(len(q_alphabet), n - L)
        elif b not in p:
            for L in range(1, n + 1):
                ans += count_end(alphabet, p, L, b) * suffix_all(q_alphabet, p, n - L)
        return ans % MOD

    @lru_cache(None)
    def count_end(alphabet, pattern, n, final):
        m = len(pattern)
        if n < m or final not in alphabet:
            return 0
        if m == 1:
            if final == pattern[0]:
                return 0
            q_alphabet = tuple(x for x in alphabet if x != pattern[0])
            return surj_end(len(q_alphabet), n, final)

        p, b = pattern[:-1], pattern[-1]
        q_alphabet = tuple(x for x in alphabet if x != b)
        if final == b:
            return 0
        ans = 0
        if p[-1] == b:
            for L in range(1, n):
                ans += (count(alphabet, p, L - 1) *
                        surj_end(len(q_alphabet), n - L, final))
        elif b not in p:
            for L in range(1, n + 1):
                ans += (count_end(alphabet, p, L, b) *
                        suffix_all(q_alphabet, p, n - L, final))
        return ans % MOD

    return count(tuple(range(1, K + 1)), tuple(X), N)

